package builtin

import (
	"encoding/json"
	"strings"
	"testing"

	"github.com/projectTHORN/proton/internal/core/tool"
)

func TestWriteFilePermissionDetailShowsManagedFile(t *testing.T) {
	ws := newTestWorkspace(t, nil)
	h := NewWriteFile(ws, &recordingCheckpointStore{id: "managed"})
	provider := h.(tool.DetailProvider)
	args, _ := json.Marshal(map[string]any{
		"file_path": "api/service.go",
		"content":   "// Code generated by x. DO NOT EDIT.\npackage api\n",
	})
	if got := provider.PermissionDetail(args); got != "api/service.go · generated file" {
		t.Fatalf("PermissionDetail() = %q", got)
	}
}

